"""Bind the scalar axis kernels to fixed four-channel arrays; no algebra."""

from pathlib import Path
import re, sys, textwrap

root = Path(sys.argv[1])
for order in (1, 2):
    lines = [
        "! Generated by gen/gen_fo_poly_axis.f90 using FortSym. Do not edit.",
        "select case (m)",
    ]
    for m in range(9):
        p = root / f"fo_axis_{m}_{order}.tmp"
        s = p.read_text()
        assignment = re.search(r"^    (?:work\d+|r[012]) =", s, re.M).start()
        declaration = s.find("    real(dp) :: work")
        start = declaration if declaration >= 0 else assignment
        body = s[start : s.rindex("end subroutine")]
        # Array dimensions apply to temporaries only, preserving the scalar DAG.
        if declaration >= 0:
            a, b = body.split("\n\n", 1)
            a = re.sub(r"\bwork\d+\b", lambda x: x[0] + "(2,2)", a)
            body = a + "\n\n" + b
        binding = {f"c{i}": f"poly(:,:,{i})" for i in range(9)}
        binding.update({f"r{i}": f"radial(:,:,{i})" for i in range(3)})
        body = re.sub(r"\b\w+\b", lambda x: binding.get(x[0], x[0]), body)
        lines.extend([f"case ({m})", "block", body.strip(), "end block"])
    lines.append("end select")
    logical = []
    pending = ""
    for line in "\n".join(lines).splitlines():
        pending += (" " if pending else "") + line.strip().removesuffix("&").lstrip(
            "&"
        ).strip()
        if not line.strip().endswith("&"):
            logical.append(pending)
            pending = ""
    result = []
    for line in logical:
        wrapped = textwrap.wrap(
            line, width=80, break_long_words=False, break_on_hyphens=False
        ) or [""]
        result.extend(
            x + (" &" if i < len(wrapped) - 1 else "") for i, x in enumerate(wrapped)
        )
    (root / f"fo_poly_axis_{order}.inc").write_text("\n".join(result) + "\n")

for path in root.glob("fo_axis_*.tmp"):
    path.unlink()
